<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>OxOS Desktop</title>
<style>
  /* ============================================================
     OxOS — a tiny Ubuntu-flavoured desktop environment
     ============================================================ */
  :root{
    --bg0:#140b1c;
    --bg1:#241731;
    --win:#2c2136;
    --win-deep:#241a2d;
    --hdr-a:#3b2d4b;
    --hdr-b:#332641;
    --txt:#efe9f4;
    --mut:#a79bb5;
    --acc:#e95420;
    --pur:#77216f;
    --line:rgba(255,255,255,.08);
  }

  *{margin:0;padding:0;box-sizing:border-box;}
  html,body{height:100%;}
  body{
    overflow:hidden;
    font-family:"Ubuntu","Ubuntu Sans",-apple-system,"Segoe UI",Roboto,"Helvetica Neue",Arial,sans-serif;
    color:var(--txt);
    background:var(--bg0);
    -webkit-font-smoothing:antialiased;
  }
  button{font:inherit;color:inherit;background:none;border:none;cursor:pointer;}
  button:focus-visible{outline:2px solid var(--acc);outline-offset:2px;}
  ::selection{background:rgba(233,84,32,.45);color:#fff;}

  ::-webkit-scrollbar{width:10px;height:10px;}
  ::-webkit-scrollbar-track{background:transparent;}
  ::-webkit-scrollbar-thumb{
    background:rgba(255,255,255,.14);
    border-radius:6px;
    border:2px solid transparent;
    background-clip:content-box;
  }
  ::-webkit-scrollbar-thumb:hover{background:rgba(255,255,255,.26);background-clip:content-box;border:2px solid transparent;}

  /* ---------------- desktop root ---------------- */
  #desktop{
    position:fixed;inset:0;overflow:hidden;
    background:
      radial-gradient(1100px 780px at 88% -12%, rgba(119,33,111,.55), transparent 62%),
      radial-gradient(900px 700px at -8% 112%, rgba(233,84,32,.26), transparent 55%),
      radial-gradient(760px 540px at 68% 84%, rgba(74,32,102,.45), transparent 60%),
      linear-gradient(158deg,#251731 0%, #1b1023 48%, #130a1b 100%);
  }
  /* faint decorative rings */
  #desktop::before{
    content:'';position:absolute;top:-190px;right:-130px;width:560px;height:560px;
    border-radius:50%;border:1.5px solid rgba(255,255,255,.05);pointer-events:none;
  }
  #desktop::after{
    content:'';position:absolute;bottom:-230px;left:-160px;width:640px;height:640px;
    border-radius:50%;border:1.5px solid rgba(255,255,255,.04);pointer-events:none;
  }
  #watermark{
    position:absolute;right:5%;bottom:6%;width:min(480px,46vw);height:auto;
    opacity:.05;pointer-events:none;transform:rotate(-8deg);z-index:0;
  }

  /* ---------------- top bar ---------------- */
  #topbar{
    position:fixed;top:0;left:0;right:0;height:32px;z-index:600;
    display:flex;align-items:center;justify-content:space-between;
    padding:0 14px;
    background:rgba(16,9,22,.78);
    backdrop-filter:blur(14px);-webkit-backdrop-filter:blur(14px);
    border-bottom:1px solid rgba(255,255,255,.06);
    font-size:12.5px;color:#ded5e6;
    user-select:none;-webkit-user-select:none;
  }
  .tb-left{display:flex;align-items:center;gap:8px;font-weight:600;letter-spacing:.4px;}
  #clock{
    position:absolute;left:50%;transform:translateX(-50%);
    font-weight:500;letter-spacing:.5px;color:#ece3f2;font-variant-numeric:tabular-nums;
  }
  .tb-right{display:flex;align-items:center;gap:11px;opacity:.85;}

  /* ---------------- dock / taskbar ---------------- */
  #taskbar{
    position:fixed;left:10px;top:50%;transform:translateY(-50%);z-index:500;
    display:flex;flex-direction:column;align-items:center;gap:10px;
    padding:12px 8px 16px;
    background:rgba(24,15,32,.72);
    backdrop-filter:blur(16px);-webkit-backdrop-filter:blur(16px);
    border:1px solid rgba(255,255,255,.09);
    border-radius:20px;
    box-shadow:0 12px 34px rgba(0,0,0,.45);
    user-select:none;-webkit-user-select:none;
  }
  .launcher{
    position:relative;width:48px;height:48px;border-radius:14px;
    display:grid;place-items:center;
    transition:background .14s, transform .14s;
  }
  .launcher:hover{background:rgba(255,255,255,.09);transform:scale(1.07);}
  .launcher:active{transform:scale(.96);}
  .launcher::before{ /* tooltip */
    content:attr(data-tip);
    position:absolute;left:calc(100% + 14px);top:50%;transform:translateY(-50%);
    padding:5px 11px;font-size:12px;font-weight:500;white-space:nowrap;
    background:rgba(8,4,12,.92);color:#f2ecf6;border-radius:8px;
    border:1px solid rgba(255,255,255,.1);
    opacity:0;pointer-events:none;transition:opacity .12s .1s;
  }
  .launcher:hover::before{opacity:1;}
  .run-dot{
    position:absolute;left:50%;bottom:-8px;transform:translateX(-50%) scale(0);
    width:5px;height:5px;border-radius:50%;background:var(--acc);
    box-shadow:0 0 7px rgba(233,84,32,.9);
    transition:transform .18s ease;
  }
  .launcher.running .run-dot{transform:translateX(-50%) scale(1);}

  /* ---------------- windows ---------------- */
  .window{
    position:absolute;z-index:10;
    display:none;flex-direction:column;
    min-width:360px;min-height:240px;
    background:linear-gradient(180deg,var(--win),var(--win-deep));
    border-radius:12px;overflow:hidden;
    box-shadow:0 16px 44px rgba(0,0,0,.5), 0 0 0 1px rgba(255,255,255,.08);
    animation:winIn .18s ease-out;
  }
  .window.open{display:flex;}
  .window.focused{
    box-shadow:0 26px 72px rgba(0,0,0,.62), 0 0 0 1px rgba(233,84,32,.42);
  }
  @keyframes winIn{
    from{opacity:0;transform:scale(.965) translateY(10px);}
    to{opacity:1;transform:none;}
  }

  .titlebar{
    display:flex;align-items:center;gap:8px;
    height:42px;flex:0 0 auto;padding:0 8px 0 14px;
    background:linear-gradient(180deg,var(--hdr-a),var(--hdr-b));
    cursor:grab;user-select:none;-webkit-user-select:none;touch-action:none;
  }
  .titlebar:active{cursor:grabbing;}
  .window:not(.focused) .titlebar{filter:saturate(.65) brightness(.9);}
  .win-title{
    flex:1;display:flex;align-items:center;gap:8px;
    font-size:13px;font-weight:600;letter-spacing:.2px;color:#f0e8f6;
  }
  .win-close{
    width:26px;height:26px;border-radius:50%;
    display:grid;place-items:center;color:#cfc3da;
    transition:background .12s,color .12s,transform .08s;
  }
  .win-close:hover{background:var(--acc);color:#fff;}
  .win-close:active{transform:scale(.92);}

  .win-status{
    flex:0 0 auto;height:26px;
    display:flex;align-items:center;justify-content:space-between;gap:12px;
    padding:0 12px;font-size:11px;color:#9d91aa;
    background:rgba(0,0,0,.18);
    border-top:1px solid rgba(255,255,255,.05);
    user-select:none;-webkit-user-select:none;
  }

  .resize-grip{
    position:absolute;right:2px;bottom:2px;width:16px;height:16px;
    cursor:nwse-resize;touch-action:none;z-index:5;
    background:linear-gradient(135deg,
      transparent 0 46%, rgba(255,255,255,.28) 46% 54%,
      transparent 54% 66%, rgba(255,255,255,.28) 66% 74%, transparent 74%);
  }

  /* ---------------- Files app ---------------- */
  .files-toolbar{
    flex:0 0 auto;height:46px;
    display:flex;align-items:center;gap:10px;padding:0 12px;
    background:rgba(0,0,0,.16);
    border-bottom:1px solid rgba(255,255,255,.06);
  }
  #files-up{
    width:30px;height:30px;border-radius:8px;flex:0 0 auto;
    display:grid;place-items:center;color:#d9cfe4;
    transition:background .12s,color .12s,opacity .12s;
  }
  #files-up:hover:not(:disabled){background:rgba(255,255,255,.1);color:#fff;}
  #files-up:disabled{opacity:.32;cursor:default;}
  #files-path{
    flex:1;height:30px;line-height:28px;padding:0 14px;
    background:rgba(0,0,0,.28);
    border:1px solid rgba(255,255,255,.07);border-radius:999px;
    font-family:ui-monospace,Menlo,Consolas,"Courier New",monospace;
    font-size:12.5px;color:#e8dff0;
    white-space:nowrap;overflow:hidden;text-overflow:ellipsis;
  }
  #files-list{
    flex:1;overflow:auto;padding:12px;
    display:grid;grid-template-columns:repeat(auto-fill,minmax(98px,1fr));
    gap:4px;align-content:start;
  }
  .fs-item{
    display:flex;flex-direction:column;align-items:center;gap:6px;
    padding:10px 6px 8px;border-radius:10px;text-align:center;
    transition:background .1s, box-shadow .1s;
  }
  .fs-item:hover{background:rgba(255,255,255,.07);}
  .fs-item.selected{background:rgba(233,84,32,.22);box-shadow:inset 0 0 0 1px rgba(233,84,32,.55);}
  .fs-name{
    font-size:12px;line-height:1.25;color:#e6ddf0;max-width:100%;
    overflow:hidden;text-overflow:ellipsis;white-space:nowrap;
  }
  .fs-empty{
    grid-column:1/-1;text-align:center;color:#8f8399;
    padding:44px 0;font-size:12.5px;
  }

  /* ---------------- Notepad app ---------------- */
  .tabstrip{
    flex:0 0 auto;height:40px;
    display:flex;align-items:flex-end;gap:4px;padding:0 8px;
    background:rgba(0,0,0,.16);
    border-bottom:1px solid rgba(255,255,255,.06);
  }
  #tabs{
    flex:1;display:flex;align-items:flex-end;gap:2px;
    height:100%;overflow-x:auto;scrollbar-width:none;
  }
  #tabs::-webkit-scrollbar{display:none;}
  .tab{
    flex:0 0 auto;max-width:172px;height:32px;margin-top:8px;
    display:flex;align-items:center;gap:6px;padding:0 6px 0 12px;
    border-radius:9px 9px 0 0;
    background:rgba(255,255,255,.05);color:#b6aac4;
    font-size:12.5px;cursor:pointer;user-select:none;-webkit-user-select:none;
    transition:background .12s,color .12s;
  }
  .tab:hover{background:rgba(255,255,255,.09);color:#ddd2e8;}
  .tab.active{background:var(--win-deep);color:#f6effb;box-shadow:inset 0 2px 0 var(--acc);}
  .tab-name{flex:1;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;}
  .tab-x{
    flex:0 0 auto;width:16px;height:16px;border-radius:50%;
    display:grid;place-items:center;font-size:11px;line-height:1;color:#9d8fae;
  }
  .tab-x:hover{background:rgba(255,255,255,.16);color:#fff;}
  #new-tab{
    flex:0 0 auto;width:26px;height:26px;margin-bottom:6px;border-radius:8px;
    display:grid;place-items:center;font-size:17px;line-height:1;color:#cfc3da;
    transition:background .12s,color .12s;
  }
  #new-tab:hover{background:rgba(255,255,255,.1);color:#fff;}
  #editor{
    flex:1;width:100%;resize:none;border:none;outline:none;
    background:var(--win-deep);color:#eee6f5;
    padding:14px 16px;
    font-family:ui-monospace,"Cascadia Code",Menlo,Consolas,"Courier New",monospace;
    font-size:13px;line-height:1.65;
    caret-color:var(--acc);
  }
  #editor::placeholder{color:#7d7189;}

  @media (prefers-reduced-motion:reduce){
    *,*::before,*::after{animation:none!important;transition:none!important;}
  }
</style>
</head>
