const filesWin   = $('files-window');
const notepadWin = $('notepad-window');
const allWins = [...document.querySelectorAll('.window')];
let zTop = 100;

const isOpen = w => w.classList.contains('open');

function focusWindow(w){
  allWins.forEach(o => o.classList.toggle('focused', o === w));
  w.style.zIndex = ++zTop;
}

function placeWindow(w){
  const dw = +w.dataset.defw || 640;
  const dh = +w.dataset.defh || 440;
  const vw = innerWidth, vh = innerHeight;
  const wide = vw > 720;
  const W = Math.min(dw, Math.max(360, vw - (wide ? 124 : 24)));
  const H = Math.min(dh, Math.max(240, vh - 56));
  const off = +(w.dataset.cascade || 0);
  let x = Math.round((vw - W) / 2) + off * 36 - 40;
  let y = Math.round((vh - H) / 2) + off * 28 - 30;
  x = Math.max(wide ? 96 : 8, Math.min(x, vw - W - 8));
  y = Math.max(40, Math.min(y, vh - H - 8));
  Object.assign(w.style, { width: W + 'px', height: H + 'px', left: x + 'px', top: y + 'px' });
}

function openWindow(w){
  if (!isOpen(w)) {
    if (!w.dataset.placed) { placeWindow(w); w.dataset.placed = '1'; }
    w.classList.add('open');
  }
  focusWindow(w);
  syncDock();
}

function closeWindow(w){
  if (w === notepadWin) flushEditor();   // make sure nothing is lost
  w.classList.remove('open');
  syncDock();
}

function syncDock(){
  $('open-files').classList.toggle('running', isOpen(filesWin));
  $('open-notepad').classList.toggle('running', isOpen(notepadWin));
}

allWins.forEach(w => {
  w.querySelector('.win-close').addEventListener('click', () => closeWindow(w));
  w.addEventListener('pointerdown', () => focusWindow(w));

  /* --- drag by titlebar --- */
  const tb = w.querySelector('.titlebar');
  tb.addEventListener('pointerdown', e => {
    if (e.target.closest('.win-close')) return;
    e.preventDefault();
    const r = w.getBoundingClientRect();
    const dx = e.clientX - r.left, dy = e.clientY - r.top;
    tb.setPointerCapture(e.pointerId);
    const mv = ev => {
      const x = Math.min(Math.max(ev.clientX - dx, -r.width + 90), innerWidth - 90);
      const y = Math.min(Math.max(ev.clientY - dy, 0), innerHeight - 42);
      w.style.left = x + 'px';
      w.style.top  = y + 'px';
    };
    const done = () => {
      tb.removeEventListener('pointermove', mv);
      tb.removeEventListener('pointerup', done);
      tb.removeEventListener('pointercancel', done);
    };
    tb.addEventListener('pointermove', mv);
    tb.addEventListener('pointerup', done);
    tb.addEventListener('pointercancel', done);
  });

  /* --- double-click titlebar: maximize / restore --- */
  let snap = null;
  tb.addEventListener('dblclick', e => {
    if (e.target.closest('.win-close')) return;
    if (snap) {
      Object.assign(w.style, snap); snap = null;
    } else {
      snap = { left: w.style.left, top: w.style.top, width: w.style.width, height: w.style.height };
      const wide = innerWidth > 720;
      Object.assign(w.style, {
        left: (wide ? 96 : 8) + 'px',
        top: '40px',
        width: (innerWidth - (wide ? 104 : 16)) + 'px',
        height: (innerHeight - 48) + 'px'
      });
    }
  });

  /* --- resize from bottom-right grip --- */
  const grip = w.querySelector('.resize-grip');
  grip.addEventListener('pointerdown', e => {
    e.preventDefault(); e.stopPropagation();
    focusWindow(w);
    const sw = w.offsetWidth, sh = w.offsetHeight;
    const sx = e.clientX, sy = e.clientY;
    grip.setPointerCapture(e.pointerId);
    const mv = ev => {
      const W = Math.max(360, Math.min(innerWidth - 16, sw + ev.clientX - sx));
      const H = Math.max(240, Math.min(innerHeight - 16, sh + ev.clientY - sy));
      w.style.width = W + 'px';
      w.style.height = H + 'px';
    };
    const done = () => {
      grip.removeEventListener('pointermove', mv);
      grip.removeEventListener('pointerup', done);
      grip.removeEventListener('pointercancel', done);
    };
    grip.addEventListener('pointermove', mv);
    grip.addEventListener('pointerup', done);
    grip.addEventListener('pointercancel', done);
  });
});

