const fileList = $('files-list');
const filePathEl = $('files-path');
const upBtn = $('files-up');
const filesMsg = $('files-msg');

let cwd = [];            // array of path segments, [] === "/"
let lastCount = 0;
let flashTimer = null;

function resolve(path){
  let n = FS;
  for (const seg of path) n = n.k[seg];
  return n;
}

function fmtSize(node){
  if (node.s) return node.s;
  const b = (node.c || '').length;
  return b < 1024 ? b + ' B' : (b / 1024).toFixed(1) + ' KB';
}

function setFsStatus(text){ filesMsg.textContent = text; }

function flashFsStatus(text){
  setFsStatus(text);
  clearTimeout(flashTimer);
  flashTimer = setTimeout(() => setFsStatus(`${lastCount} ${lastCount === 1 ? 'item' : 'items'}`), 2600);
}

function renderFiles(){
  const node = resolve(cwd);
  filePathEl.textContent = '/' + cwd.join('/');
  upBtn.disabled = cwd.length === 0;

  const entries = Object.entries(node.k).sort((a, b) => {
    const da = a[1].t === 'd', db = b[1].t === 'd';
    if (da !== db) return da ? -1 : 1;
    return a[0].localeCompare(b[0], undefined, { numeric: true, sensitivity: 'base' });
  });
  lastCount = entries.length;

  fileList.innerHTML = '';
  if (!entries.length) {
    const empty = document.createElement('div');
    empty.className = 'fs-empty';
    empty.textContent = 'This folder is empty';
    fileList.appendChild(empty);
  }

  for (const [name, child] of entries) {
    const el = document.createElement('div');
    el.className = 'fs-item';
    el.dataset.type = child.t;
    el.setAttribute('role', 'listitem');
    el.innerHTML = child.t === 'd' ? ICON_DIR : ICON_FILE;

    const nm = document.createElement('span');
    nm.className = 'fs-name';
    nm.textContent = name;                 // visible text == entry name
    el.appendChild(nm);

    el.title = child.t === 'd' ? `${name}/` : `${name} · ${fmtSize(child)}`;

    el.addEventListener('click', () => {
      fileList.querySelectorAll('.fs-item.selected').forEach(x => x.classList.remove('selected'));
      el.classList.add('selected');
    });

    el.addEventListener('dblclick', () => {
      if (child.t === 'd') {
        cwd.push(name);
        renderFiles();
      } else {
        openFileEntry(name, child);
      }
    });

    fileList.appendChild(el);
  }
  setFsStatus(`${lastCount} ${lastCount === 1 ? 'item' : 'items'}`);
}

function openFileEntry(name, node){
  if (typeof node.c === 'string') {
    openInNotepad(name, node.c);
    flashFsStatus(`Opened \u201C${name}\u201D in Notepad`);
  } else {
    flashFsStatus(`\u201C${name}\u201D is a binary file \u2014 no preview available`);
  }
}

upBtn.addEventListener('click', () => {
