/* ============================================================
   Notepad app (tabbed, persisted in localStorage)
   ============================================================ */
const tabsEl   = $('tabs');
const newBtn   = $('new-tab');
const editor   = $('editor');
const caretEl  = $('np-caret');
const countEl  = $('np-count');

const LS_KEY = 'oxos-notepad-v1';
let tabs = [];
let activeId = null;
let seq = 1;

function persist(){
  try { localStorage.setItem(LS_KEY, JSON.stringify({ v: 1, tabs, activeId })); } catch (_) {}
}

function restore(){
  try {
    const raw = localStorage.getItem(LS_KEY);
    if (raw) {
      const d = JSON.parse(raw);
      if (d && Array.isArray(d.tabs) && d.tabs.length) {
        tabs = d.tabs
          .filter(t => t && typeof t === 'object')
          .map(t => ({
            id: typeof t.id === 'number' ? t.id : seq++,
            name: String(t.name || 'Untitled').slice(0, 80),
            content: typeof t.content === 'string' ? t.content : ''
          }));
        if (!tabs.length) throw new Error('empty');
        seq = tabs.reduce((m, t) => Math.max(m, t.id), 0) + 1;
        activeId = tabs.some(t => t.id === d.activeId) ? d.activeId : tabs[0].id;
        return;
      }
    }
  } catch (_) {}
  tabs = [{ id: seq++, name: 'Untitled', content: '' }];
  activeId = tabs[0].id;
}

const cur = () => tabs.find(t => t.id === activeId);

function renderTabs(){
  tabsEl.innerHTML = '';
  for (const t of tabs) {
    const el = document.createElement('div');
    el.className = 'tab' + (t.id === activeId ? ' active' : '');
    el.dataset.id = t.id;
    el.setAttribute('role', 'tab');
    el.title = t.name;

    const nm = document.createElement('span');
    nm.className = 'tab-name';
    nm.textContent = t.name;
    el.appendChild(nm);

    const x = document.createElement('button');
    x.className = 'tab-x';
    x.textContent = '\u00D7';
    x.setAttribute('aria-label', 'Close tab ' + t.name);
    x.addEventListener('click', ev => { ev.stopPropagation(); closeTab(t.id); });
    el.appendChild(x);

    el.addEventListener('click', () => setActive(t.id));
    tabsEl.appendChild(el);
  }
  const act = tabsEl.querySelector('.tab.active');
  if (act) act.scrollIntoView({ block: 'nearest', inline: 'nearest' });
}

function setActive(id){
  if (activeId !== id) {
    const prev = cur();
    if (prev) prev.content = editor.value;   // flush before switching
    activeId = id;
  }
  const t = cur();
  editor.value = t ? t.content : '';
  renderTabs();
  persist();
  updateMeta();
}

function uniqueUntitled(){
  const names = new Set(tabs.map(t => t.name));
  let n = 'Untitled', i = 1;
  while (names.has(n)) { i++; n = 'Untitled ' + i; }
  return n;
}

function newTab(name, content){
  const t = { id: seq++, name: name !== undefined ? name : uniqueUntitled(), content: content || '' };
  tabs.push(t);
  setActive(t.id);
  editor.focus();
  return t;
}

function closeTab(id){
  const i = tabs.findIndex(t => t.id === id);
  if (i < 0) return;
  tabs.splice(i, 1);
  if (activeId === id) {
    activeId = null;
    if (!tabs.length) tabs = [{ id: seq++, name: 'Untitled', content: '' }];
    activeId = tabs[Math.min(i, tabs.length - 1)].id;
  }
  const t = cur();
  editor.value = t ? t.content : '';
  renderTabs();
  persist();
  updateMeta();
}

function updateMeta(){
  const v = editor.value;
  const i = editor.selectionStart || 0;
  const lines = v.slice(0, i).split('
');
  caretEl.textContent = `Ln ${lines.length}, Col ${lines[lines.length - 1].length + 1}`;
  const words = v.trim() ? v.trim().split(/\s+/).length : 0;
  countEl.textContent = `${v.length} characters \u00B7 ${words} words`;
}

function flushEditor(){
  const t = cur();
  if (t) t.content = editor.value;
  persist();
}

newBtn.addEventListener('click', () => newTab());

editor.addEventListener('input', () => {
  const t = cur();
  if (t) t.content = editor.value;
  persist();
  updateMeta();
});
['click', 'keyup', 'select'].forEach(ev => editor.addEventListener(ev, updateMeta));

function openInNotepad(name, content){
  const existing = tabs.find(t => t.name === name);
  if (existing) setActive(existing.id);
  else newTab(name, content);
  openWindow(notepadWin);
}

/* ============================================================
   Boot
   ============================================================ */
renderFiles();          // Files ready at "/" from the start
restore();              // pull tabs out of localStorage (or seed one)
setActive(activeId);    // sync editor + tab strip
syncDock();

/* last-chance flush so nothing typed is ever lost */
addEventListener('beforeunload', flushEditor);
})();
</script>
